#!/usr/bin/env node
// docs-check from claude-kit: a change in a documented category needs a record in docs/.
// Categories and docs paths are read from .claude/kit.json (written by kit, do not edit this file).
//
//   node .claude/kit/docs-check.mjs --base <ref>   CI: compares <ref>...HEAD
//   node .claude/kit/docs-check.mjs --hook         Claude Code Stop hook: branch changes and the working tree
//
// In CI a PR labelled docs:skip passes when its description has a line "docs:skip: <reason>"
// (env PR_LABELS — JSON array of label names, PR_BODY — description).
// Exit codes: 0 — ok or warning only, 1 — check failed or misconfigured; in --hook mode 2 asks Claude to act, once.

import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseArgs } from 'node:util';

export const globToRegExp = (glob) => {
  let out = '';
  for (let i = 0; i < glob.length; i += 1) {
    const ch = glob[i];
    if (ch === '*' && glob[i + 1] === '*') {
      if (glob[i + 2] === '/') {
        out += '(?:.*/)?';
        i += 2;
      } else {
        out += '.*';
        i += 1;
      }
    } else if (ch === '*') out += '[^/]*';
    else if (ch === '?') out += '[^/]';
    else out += ch.replace(/[.+^${}()|[\]\\]/g, '\\$&');
  }
  return new RegExp(`^${out}$`);
};

const matcher = (globs) => {
  const patterns = globs.map(globToRegExp);
  return (file) => patterns.some((pattern) => pattern.test(file));
};

// Pure decision: which categories changed without a docs record.
export const evaluate = (config, files) => {
  const isDocs = matcher(config.docs ?? []);
  const docsChanged = files.some(isDocs);
  const hits = Object.entries(config.categories ?? {})
    .map(([name, globs]) => {
      const inCategory = matcher(globs);
      return { name, files: files.filter((file) => !isDocs(file) && inCategory(file)) };
    })
    .filter((hit) => hit.files.length > 0);
  return { ok: hits.length === 0 || docsChanged, docsChanged, hits };
};

const SKIP_LABEL = 'docs:skip';
const SKIP_LINE = /^docs:skip:[ \t]*(\S.*)$/m;

export const skipDecision = (labelsJson, body) => {
  let labels = [];
  try {
    labels = JSON.parse(labelsJson ?? '[]') ?? [];
  } catch {
    labels = [];
  }
  if (!labels.includes(SKIP_LABEL)) return { skip: false };
  const match = SKIP_LINE.exec(body ?? '');
  return match === null ? { skip: false, missingReason: true } : { skip: true, reason: match[1].trim() };
};

const git = (root, args) => execFileSync('git', args, { cwd: root, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
const lines = (text) => text.split('\n').map((line) => line.trim()).filter(Boolean);

const refExists = (root, ref) => {
  try {
    git(root, ['rev-parse', '--verify', '--quiet', `${ref}^{commit}`]);
    return true;
  } catch {
    return false;
  }
};

const changedSince = (root, base) => lines(git(root, ['diff', '--name-only', '--no-renames', `${base}...HEAD`]));

const workingChanges = (root) => {
  const tracked = refExists(root, 'HEAD') ? lines(git(root, ['diff', '--name-only', '--no-renames', 'HEAD'])) : [];
  const untracked = lines(git(root, ['ls-files', '--others', '--exclude-standard']));
  return [...tracked, ...untracked];
};

const baseBranchOf = (pkg) => (pkg.answers?.branching === 'trunk' ? 'main' : 'dev');

const describe = (result) =>
  [
    'docs-check: changed without a record in docs/:',
    ...result.hits.map((hit) => `  ${hit.name}: ${hit.files.slice(0, 5).join(', ')}${hit.files.length > 5 ? ` (+${hit.files.length - 5})` : ''}`),
    'Where to write it: .claude/rules/kit/base/documentation.md.',
  ].join('\n');

const readStdin = () => {
  try {
    return readFileSync(0, 'utf8');
  } catch {
    return '';
  }
};

const main = () => {
  const { values } = parseArgs({
    options: { base: { type: 'string' }, hook: { type: 'boolean', default: false }, root: { type: 'string' } },
    strict: true,
  });
  const root = values.root ?? process.env.CLAUDE_PROJECT_DIR ?? process.cwd();

  if (values.hook) {
    let input = {};
    try {
      input = JSON.parse(readStdin() || '{}');
    } catch {
      input = {};
    }
    if (input.stop_hook_active === true) return 0;
  }

  const lockFile = join(root, '.claude', 'kit.json');
  if (!existsSync(lockFile)) {
    process.stderr.write('docs-check: .claude/kit.json not found\n');
    return values.hook ? 0 : 1;
  }
  const [pkg] = JSON.parse(readFileSync(lockFile, 'utf8')).packages ?? [];
  const config = pkg?.docsCheck;
  if (config === undefined) {
    process.stderr.write('docs-check: no docsCheck section in .claude/kit.json\n');
    return values.hook ? 0 : 1;
  }

  let files;
  try {
    if (values.hook) {
      const branch = baseBranchOf(pkg);
      const base = [`origin/${branch}`, branch].find((ref) => refExists(root, ref));
      files = [...(base === undefined ? [] : changedSince(root, base)), ...workingChanges(root)];
    } else {
      if (values.base === undefined) {
        process.stderr.write('docs-check: --base <ref> or --hook is required\n');
        return 1;
      }
      files = changedSince(root, values.base);
    }
  } catch {
    process.stderr.write('docs-check: git is unavailable or the base ref is unknown\n');
    return values.hook ? 0 : 1;
  }

  const result = evaluate(config, [...new Set(files)]);
  if (result.ok) {
    if (!values.hook) process.stdout.write('docs-check: ok\n');
    return 0;
  }

  if (values.hook) {
    process.stderr.write(`${describe(result)}\nAdd the record before finishing, or tell the user why this change needs none.\n`);
    return 2;
  }

  const skip = skipDecision(process.env.PR_LABELS, process.env.PR_BODY);
  if (skip.skip) {
    process.stdout.write(`docs-check: skipped by ${SKIP_LABEL}: ${skip.reason}\n`);
    return 0;
  }
  const message = skip.missingReason
    ? `${describe(result)}\nThe PR has the ${SKIP_LABEL} label but no "docs:skip: <reason>" line in its description.`
    : describe(result);
  const warnOnly = config.mode === 'warn';
  const prefix = process.env.GITHUB_ACTIONS === 'true' ? `::${warnOnly ? 'warning' : 'error'}::` : '';
  process.stdout.write(`${prefix}${message.replaceAll('\n', prefix ? '%0A' : '\n')}\n`);
  return warnOnly ? 0 : 1;
};

if (process.argv[1] !== undefined && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  process.exitCode = main();
}
